import { Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: { month: string; amount: number }[]
  invoices: { id: string; name: string; amount: number }[]
}

async function getDashboardData() {
  const res = await fetch('https://api.example.com/dashboard')

  if (!res.ok) {
    throw new Error('Failed to load dashboard data')
  }

  return res.json() as Promise<DashboardData>
}

async function DashboardStats() {
  const data = await getDashboardData()

  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

async function DashboardRevenue() {
  const data = await getDashboardData()

  return <RevenueChart revenue={data.revenue} />
}

async function DashboardInvoices() {
  const data = await getDashboardData()

  return <LatestInvoices invoices={data.invoices} />
}

function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4" aria-label="Loading dashboard totals">
      <div className="card" aria-hidden="true">
        <h2>Total Revenue</h2>
        <p>—</p>
      </div>
      <div className="card" aria-hidden="true">
        <h2>Total Invoices</h2>
        <p>—</p>
      </div>
    </div>
  )
}

function RevenueChartSkeleton() {
  return (
    <div className="chart" aria-label="Loading revenue">
      <h2>Revenue</h2>
      <p aria-hidden="true">Loading chart…</p>
    </div>
  )
}

function LatestInvoicesSkeleton() {
  return (
    <div className="invoices" aria-label="Loading latest invoices">
      <h2>Latest Invoices</h2>
      <p aria-hidden="true">Loading invoices…</p>
    </div>
  )
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsSkeleton />}>
        <DashboardStats />
      </Suspense>
      <Suspense fallback={<RevenueChartSkeleton />}>
        <DashboardRevenue />
      </Suspense>
      <Suspense fallback={<LatestInvoicesSkeleton />}>
        <DashboardInvoices />
      </Suspense>
    </main>
  )
}
